def fillet_edges(self):
    class EdgeSelector(cq.Selector):
        def __init__(self, pts):
            self.pts = pts
        def filter(self, objectList):
            res = []
            for o in objectList:
                c = o.Center()
                if any(abs(c.x - p[0]) < 1e-3 and abs(c.y - p[1]) < 1e-3 for p in self.pts):
                    res.append(o)
            return res

    pts = [
        (self.leg_length, 0),
        (self.leg_length, self.thickness),
        (self.thickness, self.thickness)
    ]
    self.model = self.model.edges("|Z").edges(EdgeSelector(pts)).fillet(self.fillet_radius)
